/**
 * Defines built-in help articles: Markdown body, named pictures, and the app items each article
 * covers (checked by `coverage.test.ts`).
 *
 * Pictures are `/help/<article>-<name>.webp`, generated by `e2e/tour/help.spec.ts`
 * (`pnpm help:pictures`), which also writes their arrow positions to arrows-generated.ts.
 */

import type { Arrow, DocArea, DocArticle, Gate } from '@bezier/lessons';
import type { SettingsTab } from '../settings-catalog.js';
import { ARROWS } from './arrows-generated.js';

export interface BuiltIn extends DocArticle {
  /** Keyboard actions covered (`KEY_ACTIONS` ids). */
  actions?: readonly string[];
  /** Feature types covered (the registry's `type`). */
  features?: readonly string[];
  /** Settings pages covered. */
  settings?: readonly SettingsTab[];
  /** Rail and menu entries, workspaces and other UI places covered. */
  places?: readonly string[];
  /** Minimum channel; hidden on lower channels. */
  gate?: Gate;
}

interface Written {
  id: string;
  title: string;
  area: DocArea;
  summary: string;
  keywords: string;
  /** Markdown. Pictures: `![](image:name)`; keys: `{{key:action}}`; links: `[words](doc:id)`. */
  body: string;
  /** Picture names mapped to alt text. */
  shots?: Readonly<Record<string, string>>;
  actions?: readonly string[];
  features?: readonly string[];
  settings?: readonly SettingsTab[];
  places?: readonly string[];
  gate?: Gate;
}

export function define(written: Written): BuiltIn {
  const { shots = {}, ...rest } = written;
  return {
    ...rest,
    images: Object.fromEntries(
      Object.entries(shots).map(([name, alt]) => {
        const picture = `${written.id}-${name}`;
        const arrows: readonly Arrow[] = ARROWS[picture] ?? [];
        return [name, { src: `/help/${picture}.webp`, alt, arrows }];
      }),
    ),
  };
}
